<template>
 <div class="app-container">
  <header class="workbar"><h2>订单履约</h2><span>录入 → 检查配对 / 库存 → 审核预占 → 包裹发货</span><el-button size="small" @click="router.push('/erp/package')" v-hasPermi="['erp:package:list']">包裹发货</el-button><el-button size="small" @click="router.push('/erp/shopItem')" v-hasPermi="['erp:shopItem:list']">商品配对</el-button><el-button size="small" @click="router.push('/erp/importJob')" v-hasPermi="['erp:importJob:list']">导入任务 / 失败处理</el-button></header>
  <div class="status-strip" aria-label="当前范围订单状态"><el-button size="small" :type="query.status===''?'primary':''" @click="selectStatus('')">全部 {{counts?.total??'—'}}</el-button><el-button v-for="(label,key) in statuses" :key="key" size="small" :type="query.status===key?'primary':''" @click="selectStatus(key)">{{label}} {{counts?.[countKeys[key]]??'—'}}</el-button><span>仅当前店铺 / 来源号及授权范围；未配对、缺货按所选仓库单独检查，不显示伪统计。</span></div>
  <el-form inline size="small" @submit.prevent="search">
   <el-form-item label="店铺"><el-select v-model="query.shopId" clearable filterable remote :remote-method="findShops" @visible-change="v=>v&&findShops('')" style="width:210px" placeholder="搜索授权店铺"><el-option v-for="s in shops" :key="s.shopId" :value="s.shopId" :label="s.shopCode+' · '+s.shopName"/></el-select></el-form-item>
   <el-form-item label="来源订单号"><el-input v-model="query.sourceOrderNo" maxlength="128" clearable/></el-form-item>
   <el-form-item label="状态"><el-select v-model="query.status" clearable style="width:145px"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select></el-form-item>
   <el-form-item><el-button @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
  </el-form>
  <div class="mb8"><el-button size="small" type="primary" @click="start" :disabled="busy" v-hasPermi="['erp:order:add']">录入订单</el-button><el-button size="small" @click="openUpload" :disabled="busy" v-hasPermi="['erp:order:import']">模板导入</el-button><el-button size="small" @click="template" v-hasPermi="['erp:order:import']">下载模板</el-button><el-button size="small" @click="exportList" v-hasPermi="['erp:order:export']">导出摘要</el-button><el-button size="small" @click="router.push('/erp/importJob')" v-hasPermi="['erp:importJob:list']">导入任务</el-button></div>
  <div class="batchbar"><span>本页已选 {{selected.length}} 条（最多20）</span><el-button size="small" @click="batchRef.show(selected,'review')" :disabled="busy||!selected.length" v-hasPermi="['erp:order:review']">批量审核</el-button><el-button size="small" @click="batchRef.show(selected,'cancel')" :disabled="busy||!selected.length" v-hasPermi="['erp:order:cancel']">批量取消</el-button></div>
  <el-table :data="rows" row-key="orderId" size="small" v-loading="loading" @selection-change="value=>selected=value"><el-table-column type="selection" width="42"/><el-table-column prop="sourceOrderNo" label="来源订单号" min-width="150" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}">{{statuses[row.status]||row.status}}</template></el-table-column><el-table-column prop="shopId" label="店铺ID" width="85"/><el-table-column prop="orderNo" label="内部订单号" min-width="210" show-overflow-tooltip/><el-table-column label="金额" width="150"><template #default="{row}">{{row.originalAmount??'未知'}} {{row.currency}}</template></el-table-column><el-table-column prop="orderedAt" label="下单时间" width="170"/><el-table-column label="操作" width="300" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openOrder(row,true)" :disabled="busy" v-hasPermi="['erp:order:query']">详情</el-button><el-button v-if="row.status==='PENDING_REVIEW'" link type="primary" @click="openOrder(row,false)" :disabled="busy" v-hasPermi="['erp:order:edit']">编辑</el-button><el-button v-if="row.status==='PENDING_REVIEW'" link type="primary" @click="flowRef.show(row,'review')" :disabled="busy" v-hasPermi="['erp:order:review']">审核 / 检查</el-button><el-button v-if="row.status!=='PENDING_REVIEW'" link type="primary" @click="goPackage(row)" v-hasPermi="['erp:package:list']">包裹</el-button><el-button v-if="['PENDING_REVIEW','READY_TO_SHIP'].includes(row.status)" link type="danger" @click="flowRef.show(row,'cancel')" :disabled="busy" v-hasPermi="['erp:order:cancel']">取消</el-button></template></el-table-column></el-table>
  <p v-if="!loading&&!rows.length" class="empty-hint">当前筛选下没有可见订单。可录入/导入订单，或检查店铺范围；不会自动为员工开通权限。</p>
  <OrderFulfillmentDialog ref="flowRef" @completed="load"/>
  <FulfillmentBatchDialog ref="batchRef" @completed="load"/>
  <el-button class="mt8" size="small" @click="router.push('/erp/package')" v-hasPermi="['erp:package:list']">前往包裹发货</el-button>
  <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/>
  <el-dialog v-model="open" :title="readOnly?'订单详情':form.orderId?'编辑待审核订单':'录入订单'" class="erp-dialog" width="min(1100px, calc(100vw - 24px))" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving" @close="closeOrder">
   <section v-if="readOnly" class="detail-summary"><strong>订单 #{{form.orderId}} · {{statuses[form.status]}} · v{{form.version}}</strong><p>审核 {{form.reviewedAt||'—'}} · 发货 {{form.shippedAt||'—'}} · 取消 {{form.cancelledAt||'—'}}</p><p v-if="form.cancelReason">取消原因：{{form.cancelReason}}</p><el-button v-if="form.package" size="small" @click="goPackage(form)" v-hasPermi="['erp:package:list']">查看包裹 #{{form.package.packageId}} · {{statuses[form.package.status]}}</el-button><el-button size="small" @click="goMapping(form.shopId)" v-hasPermi="['erp:shopItem:list']">查看本店商品配对</el-button></section>
   <section v-if="readOnly&&form.reviewedAt" class="snapshot"><h3>审核时的配对 / SKU快照</h3><p>固定历史，不按当前配对反查。下方原始行不因后续商品调整而改变。</p><el-table :data="form.lines" size="small" max-height="250"><el-table-column prop="sourceLineNo" label="来源行" width="100"/><el-table-column prop="shopItemCode" label="店铺SKU" min-width="140"/><el-table-column prop="skuCode" label="内部SKU" min-width="130"/><el-table-column prop="productName" label="商品快照" min-width="140"/><el-table-column prop="mappingVersion" label="配对版本" width="90"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column prop="quantity" label="数量" width="90"/></el-table></section>
   <el-form ref="formRef" :model="form" :rules="rules" label-width="95px" size="small" :disabled="saving||readOnly">
    <el-row :gutter="16"><el-col :span="12"><el-form-item label="店铺" prop="shopId"><el-select v-model="form.shopId" :disabled="!!form.orderId" filterable remote :remote-method="findShops" @visible-change="v=>v&&findShops('')" @change="shopChanged" style="width:100%"><el-option v-if="form.orderId" :value="form.shopId" :label="'店铺 #'+form.shopId"/><template v-else><el-option v-for="s in shops" :key="s.shopId" :value="s.shopId" :label="s.shopCode+' · '+s.shopName" :disabled="s.status!=='0'"/></template></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="来源单号" prop="sourceOrderNo"><el-input v-model="form.sourceOrderNo" :disabled="!!form.orderId" maxlength="128"/></el-form-item></el-col></el-row>
    <el-row :gutter="16"><el-col :span="8"><el-form-item label="收件人" prop="receiverName"><el-input v-model="form.receiverName" maxlength="120"/></el-form-item></el-col><el-col :span="8"><el-form-item label="电话"><el-input v-model="form.receiverPhone" maxlength="64"/></el-form-item></el-col><el-col :span="8"><el-form-item label="国家二字码" prop="receiverCountry"><el-input v-model="form.receiverCountry" maxlength="2" placeholder="CN / US"/></el-form-item></el-col></el-row>
    <el-row :gutter="16"><el-col :span="8"><el-form-item label="省州"><el-input v-model="form.receiverRegion" maxlength="120"/></el-form-item></el-col><el-col :span="8"><el-form-item label="城市"><el-input v-model="form.receiverCity" maxlength="120"/></el-form-item></el-col><el-col :span="8"><el-form-item label="邮编"><el-input v-model="form.receiverPostcode" maxlength="32"/></el-form-item></el-col></el-row>
    <el-form-item label="详细地址" prop="receiverAddress"><el-input v-model="form.receiverAddress" maxlength="500"/></el-form-item>
    <el-row :gutter="16"><el-col :span="6"><el-form-item label="币种" prop="currency"><el-input v-model="form.currency" maxlength="3" placeholder="CNY / USD"/></el-form-item></el-col><el-col :span="8"><el-form-item label="原始金额"><el-input v-model="form.originalAmount" maxlength="21" placeholder="留空=未知；最多4位小数"/></el-form-item></el-col><el-col :span="10"><el-form-item label="下单时间" prop="orderedAt"><el-date-picker v-model="form.orderedAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item></el-col></el-row>
    <el-table :data="form.lines" size="small" border><el-table-column label="来源行号" width="145"><template #default="{row}"><el-input v-model="row.sourceLineNo" maxlength="128" :disabled="saving||readOnly"/></template></el-table-column><el-table-column label="店铺SKU编码" min-width="160"><template #default="{row}"><el-input v-model="row.shopItemCode" maxlength="128" :disabled="saving||readOnly"/></template></el-table-column><el-table-column label="原始商品标题" min-width="220"><template #default="{row}"><el-input v-model="row.sourceTitle" maxlength="200" :disabled="saving||readOnly"/></template></el-table-column><el-table-column label="数量" width="150"><template #default="{row}"><el-input-number v-model="row.quantity" :min="1" :max="1000000000000" :precision="0" controls-position="right" :disabled="saving||readOnly" style="width:130px"/></template></el-table-column><el-table-column v-if="!readOnly" width="65"><template #default="{$index}"><el-button link type="danger" @click="form.lines.splice($index,1)" :disabled="saving||form.lines.length<=1">移除</el-button></template></el-table-column></el-table>
    <el-button v-if="!readOnly" class="mt8" size="small" @click="addLine" :disabled="saving||form.lines.length>=100">添加明细（最多100行）</el-button>
   </el-form><template #footer><el-button @click="open=false" :disabled="saving">关闭</el-button><el-button v-if="!readOnly" type="primary" @click="saveOrder" :loading="saving">保存为待审核</el-button></template>
  </el-dialog>
  <el-dialog v-model="uploadOpen" title="按固定模板导入订单" class="erp-dialog" width="min(580px, calc(100vw - 24px))" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving" @close="closeUpload">
   <el-alert title="最多5000行，每单最多100行，文件≤10MiB且受企业配额限制。编号、电话、邮编用文本，不含公式。同单字段不一致整单失败。原文件私有保留24小时。" type="warning" :closable="false"/>
   <el-form label-width="75px" class="mt8" size="small"><el-form-item label="店铺"><el-select v-model="upload.shopId" filterable remote :remote-method="findShops" @visible-change="v=>v&&findShops('')" :disabled="saving" style="width:100%"><el-option v-for="s in shops" :key="s.shopId" :value="s.shopId" :label="s.shopCode+' · '+s.shopName" :disabled="s.status!=='0'"/></el-select></el-form-item><el-form-item label="文件"><input ref="fileInput" type="file" accept=".xlsx" :disabled="saving" @change="chooseFile"/></el-form-item></el-form>
   <template #footer><el-button @click="uploadOpen=false" :disabled="saving">关闭</el-button><el-button type="primary" @click="submitImport" :loading="saving">提交任务</el-button></template>
  </el-dialog>
 </div>
</template>
<script setup>
import { ref, reactive, computed, onMounted,watch,onBeforeUnmount } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { saveAs } from 'file-saver'
import { checkPermi } from '@/utils/permission'
import { download } from '@/utils/request'
import { listErpShop } from '@/api/erp/shop'
import { listOrders, getOrder, addOrder, editOrder, importOrders, orderTemplate,orderWorkbench } from '@/api/erp/order'
import OrderFulfillmentDialog from './OrderFulfillmentDialog.vue'
import FulfillmentBatchDialog from './FulfillmentBatchDialog.vue'
const flowRef=ref(),batchRef=ref(),selected=ref([]),counts=ref(null),route=useRoute()
const router=useRouter(),rows=ref([]),total=ref(0),loading=ref(false),saving=ref(false),detailLoading=ref(false),shops=ref([]),open=ref(false),readOnly=ref(false),uploadOpen=ref(false),form=ref({lines:[]}),formRef=ref(),fileInput=ref()
const busy=computed(()=>saving.value||detailLoading.value)
const query=reactive({pageNum:1,pageSize:10,shopId:undefined,sourceOrderNo:'',status:''}),upload=reactive({shopId:undefined,file:null,requestKey:''})
const statuses={PENDING_REVIEW:'待审核',READY_TO_SHIP:'待发货',SHIPPED:'已发货',CANCELLED:'已取消'}
const countKeys={PENDING_REVIEW:'pendingReview',READY_TO_SHIP:'readyToShip',SHIPPED:'shipped',CANCELLED:'cancelled'}
const rules=Object.fromEntries(['shopId','sourceOrderNo','receiverName','receiverCountry','receiverAddress','currency','orderedAt'].map(k=>[k,[{required:true,message:'请填写必填项',trigger:'blur'}]]))
let listSequence=0,detailSequence=0,shopSequence=0
async function load(){const ticket=++listSequence;loading.value=true;try{const [r,summary]=await Promise.all([listOrders({...query}),orderWorkbench({shopId:query.shopId,sourceOrderNo:query.sourceOrderNo}).catch(()=>null)]);if(ticket===listSequence){rows.value=r.rows;total.value=r.total;counts.value=summary?.data||null;selected.value=[]}}finally{if(ticket===listSequence)loading.value=false}}
function selectStatus(status){query.status=status;return search()}
function goPackage(row){if(!checkPermi(['erp:package:list']))return;const target={orderId:String(row.orderId)};if(row.package&&checkPermi(['erp:package:query']))target.packageId=String(row.package.packageId);return router.push({path:'/erp/package',query:target})}
function goMapping(shopId){if(checkPermi(['erp:shopItem:list']))return router.push({path:'/erp/shopItem',query:{shopId:String(shopId)}})}
function safeID(raw){return typeof raw==='string'&&/^[1-9]\d*$/.test(raw)&&Number.isSafeInteger(Number(raw))?Number(raw):null}
async function followOrderLink(){if(saving.value)return;++detailSequence;detailLoading.value=false;open.value=false;form.value={lines:[]};const raw=route.query.orderId;if(raw===undefined)return;const id=safeID(raw);if(!id){ElMessage.warning('订单链接编号无效');return}if(!checkPermi(['erp:order:query'])){ElMessage.warning('查看订单需要订单详情权限');return}return openOrder({orderId:id},true).catch(()=>{})}
watch(()=>route.query.orderId,followOrderLink)
onBeforeUnmount(()=>{++listSequence;++detailSequence;++shopSequence;form.value={lines:[]};upload.file=null})
function search(){query.pageNum=1;return load()}
function reset(){Object.assign(query,{shopId:undefined,sourceOrderNo:'',status:''});return search()}
async function findShops(shopName){if(!checkPermi(['erp:shop:list'])){ElMessage.warning('选择店铺需要店铺列表权限');return}const ticket=++shopSequence;const r=await listErpShop({shopName,pageNum:1,pageSize:100});if(ticket===shopSequence)shops.value=r.rows}
function addLine(){form.value.lines.push({sourceLineNo:String(form.value.lines.length+1).padStart(3,'0'),shopItemCode:'',sourceTitle:'',quantity:1})}
function start(){if(busy.value)return;++detailSequence;form.value={shopId:query.shopId,sourceOrderNo:'',requestKey:crypto.randomUUID(),receiverName:'',receiverPhone:'',receiverCountry:'CN',receiverRegion:'',receiverCity:'',receiverPostcode:'',receiverAddress:'',currency:'CNY',originalAmount:'',orderedAt:'',lines:[]};addLine();readOnly.value=false;open.value=true;formRef.value?.clearValidate()}
function shopChanged(id){const shop=shops.value.find(s=>s.shopId===id);if(shop)form.value.currency=shop.currency}
async function openOrder(row,readonly){if(busy.value)return;const ticket=++detailSequence;detailLoading.value=true;try{const r=await getOrder(row.orderId);if(ticket!==detailSequence)return;form.value={...r.data,requestKey:crypto.randomUUID(),originalAmount:r.data.originalAmount??'',lines:r.data.lines.map(l=>({...l}))};readOnly.value=readonly;open.value=true;formRef.value?.clearValidate()}finally{if(ticket===detailSequence)detailLoading.value=false}}
function closeOrder(){if(open.value)return;++detailSequence;detailLoading.value=false;form.value={lines:[]};formRef.value?.clearValidate()}
async function saveOrder(){if(saving.value||readOnly.value||!open.value)return;saving.value=true;try{await formRef.value.validate();const source=form.value,id=source.orderId,payload=Object.fromEntries(['shopId','sourceOrderNo','requestKey','version','receiverName','receiverPhone','receiverCountry','receiverRegion','receiverCity','receiverPostcode','receiverAddress','currency','orderedAt'].map(k=>[k,source[k]]));payload.originalAmount=source.originalAmount===''?null:source.originalAmount;payload.lines=source.lines.map(l=>({sourceLineNo:l.sourceLineNo,shopItemCode:l.shopItemCode,sourceTitle:l.sourceTitle,quantity:l.quantity}));if(id)await editOrder(id,payload);else await addOrder(payload);open.value=false;form.value={lines:[]};ElMessage.success('已保存待审核订单，库存未变化');await load()}finally{saving.value=false}}
function openUpload(){if(busy.value)return;Object.assign(upload,{shopId:query.shopId,file:null,requestKey:crypto.randomUUID()});if(fileInput.value)fileInput.value.value='';uploadOpen.value=true}
function chooseFile(e){upload.file=e.target.files?.[0]||null;upload.requestKey=crypto.randomUUID()}
function closeUpload(){if(uploadOpen.value)return;upload.file=null;if(fileInput.value)fileInput.value.value=''}
async function submitImport(){if(saving.value||!uploadOpen.value)return;if(!upload.shopId||!upload.file){ElMessage.warning('请选择店铺和XLSX文件');return}if(upload.file.size>10*1024*1024){ElMessage.warning('文件不得超过10MiB');return}saving.value=true;try{const data=new FormData();data.append('shopId',upload.shopId);data.append('requestKey',upload.requestKey);data.append('file',upload.file);const r=await importOrders(data);uploadOpen.value=false;upload.file=null;ElMessage.success(`任务 #${r.data.jobId} 已提交，请到导入任务查看结果`)}finally{saving.value=false}}
async function saveDownload(blob,name){if(blob.type==='application/json'){const v=JSON.parse(await blob.text());ElMessage.warning(v.msg||'下载失败');return}saveAs(blob,name)}
async function template(){await saveDownload(await orderTemplate(),'订单导入模板.xlsx')}
function exportList(){return download('/erp/order/export',{shopId:query.shopId,status:query.status,sourceOrderNo:query.sourceOrderNo},'订单摘要.xlsx',{headers:{repeatSubmit:false}})}
onMounted(()=>{load();followOrderLink()})
</script>
<style scoped>
.workbar,.status-strip,.batchbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:12px}.workbar{border-bottom:1px solid var(--el-border-color-lighter);padding-bottom:10px}.workbar h2{font-size:18px;margin:0 8px 0 0}.workbar span,.status-strip span,.batchbar span,.empty-hint,.snapshot p,.detail-summary p{font-size:12px;color:var(--el-text-color-secondary)}.status-strip .el-button+.el-button,.batchbar .el-button+.el-button,.workbar .el-button+.el-button{margin-left:0}.detail-summary,.snapshot{padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid var(--el-border-color-lighter)}.snapshot h3{font-size:14px;margin:8px 0}.empty-hint{padding:10px 0} :deep(.el-dialog__body){max-height:calc(100dvh - 200px);overflow:auto} :deep(.el-table .cell){line-height:22px}
@media(max-width:640px){.workbar span,.status-strip span{width:100%}:deep(.el-col){max-width:100%;flex-basis:100%}:deep(.el-form-item){margin-bottom:12px}}
</style>
